package middleware

imports: context, encoding/json, net/http, strings

type contextKey string
const IdentityKey contextKey = "auth_identity"

type AuthStrategy interface {
  Authenticate(r *http.Request) (identity string, err error)
}

type BearerTokenStrategy struct { ValidTokens map[string]string }
func (b BearerTokenStrategy) Authenticate(r):
  header := r.Header.Get("Authorization")
  if !strings.HasPrefix(header, "Bearer "): return "", error
  token := strings.TrimPrefix(header, "Bearer ")
  if identity, ok := ValidTokens[token]: return identity, nil
  return "", errors.New("invalid bearer token")

type APIKeyStrategy struct { ValidKeys map[string]string }
func (a APIKeyStrategy) Authenticate(r):
  key := r.Header.Get("X-API-Key")
  if key == "": return "", error
  if identity, ok := ValidKeys[key]: return identity, nil
  return "", errors.New("invalid api key")

func AuthMiddleware(strategies ...AuthStrategy) func(http.Handler) http.Handler:
  return func(next) func(w, r):
    var triedStrategies []string
    for each strategy:
      identity, err := strategy.Authenticate(r)
      if err == nil:
        ctx := context.WithValue(r.Context(), IdentityKey, identity)
        next.ServeHTTP(w, r.WithContext(ctx))
        return
      triedStrategies = append(name of strategy type)
    w.WriteHeader(401)
    json.NewEncoder(w).Encode({error: "unauthorized", strategies_tried: triedStrategies})
